Implemented in `middleware.ts:1`.

```ts
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

export function middleware(request: NextRequest) {
  const requestId = crypto.randomUUID();

  console.log(`[middleware] ${request.nextUrl.pathname}`);

  const response = NextResponse.next();
  response.headers.set("X-Request-Id", requestId);

  return response;
}

export const config = {
  matcher: "/:path*",
};
```

This logs each request pathname and adds a unique `X-Request-Id` header to all matched responses.  
I also validated with `npm run build` (it succeeds; Next.js shows a deprecation warning that `middleware` is being renamed to `proxy` in newer versions).
